def histogram(test):
    if not test:
        return {}

    counts = {}
    for char in test.lower():
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1

    max_count = max(counts.values())
    result = {k: v for k, v in counts.items() if v == max_count}

    return result if len(result) > 1 else list(result.keys())[0]

# Test cases
