def sort_array(arr):
    def count_ones(n):
        return bin(n).count('1')

    def decimal_sort(a, b):
        if count_ones(a) == count_ones(b):
            return a - b
        return count_ones(a) - count_ones(b)

    arr.sort(key=decimal_sort)
    return arr
```

